<?php require __DIR__.'/../lib/bootstrap.php';require __DIR__.'/../lib/layout.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['act']??'';$id=(int)($_POST['id']??0);if($act==='save'){$vi=trim($_POST['name_vi']??'');$en=trim($_POST['name_en']??'');$zh=trim($_POST['name_zh']??'');$base=$vi?:($en?:$zh);$sort=(int)($_POST['sort_order']??0);$active=isset($_POST['active'])?1:0;if($base!==''){if($id)db()->prepare('UPDATE categories SET name=?,name_vi=?,name_en=?,name_zh=?,sort_order=?,active=? WHERE id=?')->execute([$base,$vi?:null,$en?:null,$zh?:null,$sort,$active,$id]);else db()->prepare('INSERT INTO categories(name,name_vi,name_en,name_zh,sort_order,active) VALUES(?,?,?,?,?,?)')->execute([$base,$vi?:null,$en?:null,$zh?:null,$sort,$active]);}}elseif($act==='delete'&&$id){$st=db()->prepare('SELECT COUNT(*) FROM products WHERE category_id=?');$st->execute([$id]);if((int)$st->fetchColumn()===0)db()->prepare('DELETE FROM categories WHERE id=?')->execute([$id]);}redirect('categories.php');}
$rows=db()->query('SELECT * FROM categories ORDER BY sort_order,id')->fetchAll();admin_header(t('drink_categories'));?>
